{% extends 'dashboard.html' %}
{% load static %}
{% load humanize %} {# This is good for intcomma #}
{% block title %}
Delinquent Accounts
{% endblock title %}
{% block style %}
    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">
    <style>
        body {
            background-color: #dbe3e5; /* Soft gray-blue background */
        }
        .container {
            max-width: 100%;
            margin-top: 20px;
        }
        #barangay {
        width: 200px; /* Reduced width */
        display: inline-block;
    }

        /* New button2 styles applied */
        .button2 {
            background-color: var(--main-color);
            color: white;
            padding: 8px 30px;
            border: none;
            border-radius: 15px;
            box-shadow:
                inset 0px -8px 7px 0 rgba(0, 0, 0, 0.24),
                inset 0px 5px 7px 0 rgba(255, 255, 255, 0.52),
                0px 6px 6px 0 rgba(0, 0, 0, 0.19);
            transition: all ease 0.3s;
        }
        .btn.button2:hover {
            background: var(--main-color);
            color: #ffffff;
            border-radius: 30px;
            box-shadow:
                inset 0px -8px 7px 0 rgba(0, 0, 0, 0.39),
                inset 0px 5px 7px 0 rgba(230, 236, 235, 0.85),
                0px 6px 6px 0 rgba(0, 0, 0, 0.19);
            transition: all ease-in 0.5s;
        }
        .btn.button2:focus {
            background: var(--main-color);
            color: #ffffff;
            border-radius: 30px;
            box-shadow:
                inset 0px 4px 7px 0 rgba(0, 0, 0, 0.27),
                inset 0px -5px 7px 0 rgba(230, 236, 235, 0.85);
            transition: all 0.1s;
        }

        .table {
            background-color: white;
            overflow: hidden;
        }
        th {
            background-color: #0b6778;
            color: white;
            text-align: center;
            background-color: #09525f !important;
            color: white !important;
        }

        td {
            text-align: center;
        }
        .pagination .page-link {
            color: #0b6778;
        }
        .pagination .active .page-link {
            background-color: #0b6778;
            border-color: #0b6778;
            color: white;
        }
    </style>
{% endblock style %}

    {% block script %}
    {% endblock script %}
    {% block delinquent_accounts %}

<div class="container">
    <div class="mb-3">
        <label for="barangay" class="form-label">Barangay:</label>
        <select id="barangay" class="form-select">
            <option value="All" {% if selected_barangay == "All" %}selected{% endif %}>All</option>
            <option value="Anao" {% if selected_barangay == "Anao" %}selected{% endif %}>Anao</option>
            <option value="Cagsing" {% if selected_barangay == "Cagsing" %}selected{% endif %}>Cagsing</option>
            <option value="Calabawan" {% if selected_barangay == "Calabawan" %}selected{% endif %}>Calabawan</option>
            <option value="Cambagte" {% if selected_barangay == "Cambagte" %}selected{% endif %}>Cambagte</option>
            <option value="Campisong" {% if selected_barangay == "Campisong" %}selected{% endif %}>Campisong</option>
            <option value="Cañorong" {% if selected_barangay == "Cañorong" %}selected{% endif %}>Cañorong</option>
            <option value="Guiwanon" {% if selected_barangay == "Guiwanon" %}selected{% endif %}>Guiwanon</option>
            <option value="Looc" {% if selected_barangay == "Looc" %}selected{% endif %}>Looc</option>
            <option value="Malatbo" {% if selected_barangay == "Malatbo" %}selected{% endif %}>Malatbo</option>
            <option value="Mangaco" {% if selected_barangay == "Mangaco" %}selected{% endif %}>Mangaco</option>
            <option value="Palanas" {% if selected_barangay == "Palanas" %}selected{% endif %}>Palanas</option>
            <option value="Poblacion" {% if selected_barangay == "Poblacion" %}selected{% endif %}>Poblacion</option>
            <option value="Salamanca" {% if selected_barangay == "Salamanca" %}selected{% endif %}>Salamanca</option>
            <option value="San Roque" {% if selected_barangay == "San Roque" %}selected{% endif %}>San Roque</option>
            </select>
    </div>

    <script>
        document.getElementById("barangay").addEventListener("change", function() {
            const selectedBarangay = this.value;
            window.location.href = "?barangay=" + encodeURIComponent(selectedBarangay);
        });
    </script>

    <div class="d-flex gap-3 mb-4">
        <button class="btn button2">Delinquent Accounts</button>
        <a href="{% url 'delinquent_months' %}">
            <button type="button" class="btn button2">Delinquent Months</button>
        </a>
    </div>

    <h2 class="text-center mb-4">Delinquent Accounts</h2>

    <div class="table-responsive">
        <table class="table table-bordered">
            <thead>
                <tr>
                    <th>Account ID</th>
                    <th>Name</th>
                    {# It's often helpful to display the Home Address if it's a filter option #}
                    <th>Home Address</th>
                    <th>Total Delinquent Amount</th>
                    <th>No. of Unpaid Months</th>
                </tr>
            </thead>

            <tbody>
                {% for consumer in page_obj %}
                <tr>
                    {# Accessing attributes directly from the consumer object #}
                    <td>{{ consumer.consumer_id }}</td>
                    {# Concatenate first and last name #}
                    <td>{{ consumer.lastname }}, {{ consumer.firstname }}</td> 
                    <td>{{ consumer.homeaddress }}</td> {# Displaying home address #}
                    {# Use floatformat:2 for currency and intcomma for thousands separator #}
                    <td>₱{{ consumer.total_delinquent|floatformat:2|intcomma }}</td> 
                    <td>{{ consumer.delinquent_months }}</td> 
                </tr>
                {% empty %}
                <tr>
                    <td colspan="5">No delinquent accounts found.</td> {# Adjusted colspan to match new column count #}
                </tr>
                {% endfor %}
            </tbody>
        </table>
    </div>

    <nav>
        <ul class="pagination justify-content-center">
            {% if page_obj.has_previous %}
                <li class="page-item">
                    <a class="page-link" href="?page=1&barangay={{ selected_barangay }}">First</a>
                </li>
                <li class="page-item">
                    <a class="page-link" href="?page={{ page_obj.previous_page_number }}&barangay={{ selected_barangay }}">Previous</a>
                </li>
            {% endif %}

            {% for num in page_obj.paginator.page_range %}
                {% if page_obj.number == num %}
                    <li class="page-item active"><a class="page-link" href="?page={{ num }}&barangay={{ selected_barangay }}">{{ num }}</a></li>
                {% elif num > page_obj.number|add:"-3" and num < page_obj.number|add:"3" %}
                    <li class="page-item"><a class="page-link" href="?page={{ num }}&barangay={{ selected_barangay }}">{{ num }}</a></li>
                {% endif %}
            {% endfor %}

            {% if page_obj.has_next %}
                <li class="page-item">
                    <a class="page-link" href="?page={{ page_obj.next_page_number }}&barangay={{ selected_barangay }}">Next</a>
                </li>
                <li class="page-item">
                    <a class="page-link" href="?page={{ page_obj.paginator.num_pages }}&barangay={{ selected_barangay }}">Last</a>
                </li>
            {% endif %}
        </ul>
    </nav>
</div>

{% endblock delinquent_accounts %}
